toolArgs.file_text:
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 1rem;
    flex-wrap: wrap;
    gap: 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 90px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.85rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
    transition: all 0.2s;
}

.step.active .step-circle {
    background: #0d6efd;
    border-color: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    background: #198754;
    border-color: #198754;
    color: #fff;
}

.step.future .step-circle {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
    margin-top: 4px;
    text-align: center;
    color: #6c757d;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    min-width: 20px;
    max-width: 60px;
    align-self: center;
    margin-bottom: 18px;
}

.step-connector.completed {
    background: #198754;
}

.checkmark {
    font-size: 1rem;
}

